func NewDetailValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (DetailValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing DetailValue Attribute Value",
				"While creating a DetailValue value, a missing attribute value was detected. "+
					"A DetailValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("DetailValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid DetailValue Attribute Type",
				"While creating a DetailValue value, an invalid attribute value was detected. "+
					"A DetailValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("DetailValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("DetailValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra DetailValue Attribute Value",
				"While creating a DetailValue value, an extra attribute value was detected. "+
					"A DetailValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra DetailValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewDetailValueUnknown(), diags
	}

	formatAttribute, ok := attributes["format"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`format is missing from object`)

		return NewDetailValueUnknown(), diags
	}

	formatVal, ok := formatAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`format expected to be basetypes.StringValue, was: %T`, formatAttribute))
	}

	lockfilePathAttribute, ok := attributes["lockfile_path"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`lockfile_path is missing from object`)

		return NewDetailValueUnknown(), diags
	}

	lockfilePathVal, ok := lockfilePathAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`lockfile_path expected to be basetypes.StringValue, was: %T`, lockfilePathAttribute))
	}

	packageNameAttribute, ok := attributes["package_name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`package_name is missing from object`)

		return NewDetailValueUnknown(), diags
	}

	packageNameVal, ok := packageNameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`package_name expected to be basetypes.StringValue, was: %T`, packageNameAttribute))
	}

	resolvedAttribute, ok := attributes["resolved"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`resolved is missing from object`)

		return NewDetailValueUnknown(), diags
	}

	resolvedVal, ok := resolvedAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`resolved expected to be basetypes.StringValue, was: %T`, resolvedAttribute))
	}

	versionReqAttribute, ok := attributes["version_req"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`version_req is missing from object`)

		return NewDetailValueUnknown(), diags
	}

	versionReqVal, ok := versionReqAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`version_req expected to be basetypes.StringValue, was: %T`, versionReqAttribute))
	}

	if diags.HasError() {
		return NewDetailValueUnknown(), diags
	}

	return DetailValue{
		Format:       formatVal,
		LockfilePath: lockfilePathVal,
		PackageName:  packageNameVal,
		Resolved:     resolvedVal,
		VersionReq:   versionReqVal,
		state:        attr.ValueStateKnown,
	}, diags
}

func NewDetailValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) DetailValue {
	object, diags := NewDetailValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewDetailValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t DetailType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewDetailValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewDetailValueUnknown(), nil
	}

	if in.IsNull() {
		return NewDetailValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewDetailValueMust(DetailValue{}.AttributeTypes(ctx), attributes), nil
}

