func NewToValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (ToValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing ToValue Attribute Value",
				"While creating a ToValue value, a missing attribute value was detected. "+
					"A ToValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ToValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid ToValue Attribute Type",
				"While creating a ToValue value, an invalid attribute value was detected. "+
					"A ToValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("ToValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("ToValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra ToValue Attribute Value",
				"While creating a ToValue value, an extra attribute value was detected. "+
					"A ToValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra ToValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewToValueUnknown(), diags
	}

	displayNameAttribute, ok := attributes["display_name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`display_name is missing from object`)

		return NewToValueUnknown(), diags
	}

	displayNameVal, ok := displayNameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`display_name expected to be basetypes.StringValue, was: %T`, displayNameAttribute))
	}

	externalAttribute, ok := attributes["external"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`external is missing from object`)

		return NewToValueUnknown(), diags
	}

	externalVal, ok := externalAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`external expected to be basetypes.BoolValue, was: %T`, externalAttribute))
	}

	groupIdAttribute, ok := attributes["group_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`group_id is missing from object`)

		return NewToValueUnknown(), diags
	}

	groupIdVal, ok := groupIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`group_id expected to be basetypes.StringValue, was: %T`, groupIdAttribute))
	}

	kindAttribute, ok := attributes["kind"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`kind is missing from object`)

		return NewToValueUnknown(), diags
	}

	kindVal, ok := kindAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`kind expected to be basetypes.StringValue, was: %T`, kindAttribute))
	}

	lifecycleAttribute, ok := attributes["lifecycle"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`lifecycle is missing from object`)

		return NewToValueUnknown(), diags
	}

	lifecycleVal, ok := lifecycleAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`lifecycle expected to be basetypes.StringValue, was: %T`, lifecycleAttribute))
	}

	orphanedAtAttribute, ok := attributes["orphaned_at"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`orphaned_at is missing from object`)

		return NewToValueUnknown(), diags
	}

	orphanedAtVal, ok := orphanedAtAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`orphaned_at expected to be basetypes.StringValue, was: %T`, orphanedAtAttribute))
	}

	serviceIdAttribute, ok := attributes["service_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`service_id is missing from object`)

		return NewToValueUnknown(), diags
	}

	serviceIdVal, ok := serviceIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`service_id expected to be basetypes.StringValue, was: %T`, serviceIdAttribute))
	}

	slugAttribute, ok := attributes["slug"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`slug is missing from object`)

		return NewToValueUnknown(), diags
	}

	slugVal, ok := slugAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`slug expected to be basetypes.StringValue, was: %T`, slugAttribute))
	}

	sourceAttribute, ok := attributes["source"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`source is missing from object`)

		return NewToValueUnknown(), diags
	}

	sourceVal, ok := sourceAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`source expected to be basetypes.StringValue, was: %T`, sourceAttribute))
	}

	if diags.HasError() {
		return NewToValueUnknown(), diags
	}

	return ToValue{
		DisplayName: displayNameVal,
		External:    externalVal,
		GroupId:     groupIdVal,
		Kind:        kindVal,
		Lifecycle:   lifecycleVal,
		OrphanedAt:  orphanedAtVal,
		ServiceId:   serviceIdVal,
		Slug:        slugVal,
		Source:      sourceVal,
		state:       attr.ValueStateKnown,
	}, diags
}

func NewToValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) ToValue {
	object, diags := NewToValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewToValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t ToType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewToValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewToValueUnknown(), nil
	}

	if in.IsNull() {
		return NewToValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewToValueMust(ToValue{}.AttributeTypes(ctx), attributes), nil
}

func (t ToType) ValueType(ctx context.Context) attr.Value {
	return ToValue{}
}

var _ basetypes.ObjectValuable = ToValue{}

type ToValue struct {
	DisplayName basetypes.StringValue `tfsdk:"display_name"`
	External    basetypes.BoolValue   `tfsdk:"external"`
	GroupId     basetypes.StringValue `tfsdk:"group_id"`
	Kind        basetypes.StringValue `tfsdk:"kind"`
	Lifecycle   basetypes.StringValue `tfsdk:"lifecycle"`
	OrphanedAt  basetypes.StringValue `tfsdk:"orphaned_at"`
	ServiceId   basetypes.StringValue `tfsdk:"service_id"`
	Slug        basetypes.StringValue `tfsdk:"slug"`
	Source      basetypes.StringValue `tfsdk:"source"`
	state       attr.ValueState
}

func (v ToValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 9)

	var val tftypes.Value
	var err error

	attrTypes["display_name"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["external"] = basetypes.BoolType{}.TerraformType(ctx)
	attrTypes["group_id"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["kind"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["lifecycle"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["orphaned_at"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["service_id"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["slug"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["source"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 9)

		val, err = v.DisplayName.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["display_name"] = val

		val, err = v.External.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["external"] = val

		val, err = v.GroupId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["group_id"] = val

		val, err = v.Kind.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["kind"] = val

		val, err = v.Lifecycle.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["lifecycle"] = val

		val, err = v.OrphanedAt.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["orphaned_at"] = val

		val, err = v.ServiceId.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["service_id"] = val

		val, err = v.Slug.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["slug"] = val

		val, err = v.Source.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["source"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v ToValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v ToValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v ToValue) String() string {
	return "ToValue"
}

func (v ToValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"display_name": basetypes.StringType{},
		"external":     basetypes.BoolType{},
		"group_id":     basetypes.StringType{},
		"kind":         basetypes.StringType{},
		"lifecycle":    basetypes.StringType{},
		"orphaned_at":  basetypes.StringType{},
		"service_id":   basetypes.StringType{},
		"slug":         basetypes.StringType{},
		"source":       basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"display_name": v.DisplayName,
			"external":     v.External,
			"group_id":     v.GroupId,
			"kind":         v.Kind,
			"lifecycle":    v.Lifecycle,
			"orphaned_at":  v.OrphanedAt,
			"service_id":   v.ServiceId,
			"slug":         v.Slug,
			"source":       v.Source,
		})

	return objVal, diags
}

func (v ToValue) Equal(o attr.Value) bool {
	other, ok := o.(ToValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.DisplayName.Equal(other.DisplayName) {
		return false
	}

	if !v.External.Equal(other.External) {
		return false
	}

	if !v.GroupId.Equal(other.GroupId) {
		return false
	}

	if !v.Kind.Equal(other.Kind) {
		return false
	}

	if !v.Lifecycle.Equal(other.Lifecycle) {
		return false
	}

	if !v.OrphanedAt.Equal(other.OrphanedAt) {
		return false
	}

	if !v.ServiceId.Equal(other.ServiceId) {
		return false
	}

	if !v.Slug.Equal(other.Slug) {
		return false
	}

	if !v.Source.Equal(other.Source) {
		return false
	}

	return true
}

func (v ToValue) Type(ctx context.Context) attr.Type {
	return ToType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v ToValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"display_name": basetypes.StringType{},
		"external":     basetypes.BoolType{},
		"group_id":     basetypes.StringType{},
		"kind":         basetypes.StringType{},
		"lifecycle":    basetypes.StringType{},
		"orphaned_at":  basetypes.StringType{},
		"service_id":   basetypes.StringType{},
		"slug":         basetypes.StringType{},
		"source":       basetypes.StringType{},
	}
}
